INSERT IGNORE INTO door_swipe_rule_record (
    record_id, card_number, channel_code, channel_name, open_type,
    person_code, person_id, person_name, department_id,
    swing_time, create_time, open_result, enter_or_exit, raw_json
) VALUES (
    #{recordId}, #{cardNumber}, #{channelCode}, #{channelName}, #{openType},
    #{personCode}, #{personId}, #{personName}, #{departmentId},
    #{swingTime}, #{createTime}, #{openResult}, #{enterOrExit}, #{rawJson}
)

mapper.sql:
WHERE 1 = 1
AND channel_code = #{channelCode}

    AND (person_name LIKE CONCAT('%', #{person}, '%')
         OR person_code LIKE CONCAT('%', #{person}, '%')
         OR card_number LIKE CONCAT('%', #{person}, '%'))

AND open_type = #{openType}
AND swing_time >= #{startTime}
AND swing_time <= #{endTime}
